int dasmV_init(void) {
  return dasmV_do_init();
}

void dasmV_execute(lua_State *L, CallInfo *ci) {
  dasm_execute_fn fn;
  const Instruction *pc;
  LClosure *cl;
  Proto *p;

  if (!g_dasm_initialized) {
    if (dasmV_do_init() != 0) {
      return;
    }
  }

  pc = ci->u.l.savedpc;
  cl = clLvalue(s2v(ci->func.p));
  p = cl->p;
  if (GET_OPCODE(*pc) == OP_VARARGPREP) {
    int a = GETARG_A(*pc);
    ci->u.l.savedpc = pc;
    luaT_adjustvarargs(L, a, ci, p);
    if (l_unlikely(ci->u.l.trap)) {
      extern void luaD_hookcall(lua_State *L, CallInfo *ci);
      luaD_hookcall(L, ci);
      L->oldpc = 1;
    }
    ci->u.l.savedpc = pc + 1;
  }

  fn = (dasm_execute_fn)g_dasm_globals[DASM_VM_vm_execute];
  fn(L, ci);
  luaV_execute(L, ci);
}
